window.__denzingerWorks["dz_075"] = {"id":"dz_075","a":"Denzinger (1819-1883) — 11e éd., Bannwart S.J., 1911","t":"URBANUS III 1185—1187","u":"https://archive.org/details/enchiridionsymbo01denz","c":[{"t":"URBANUS III 1185—1187","s":[{"t":"ep. cConsuluit nos» ad presbyterum quendam Brixiensem","p":["403 Consuluit nos tua devotio, an ille in iudicio animaruni 1475 (340)quasi usurarius debeat iudicari, qui non alias mutuo traditurus, eo proposito mutuam pecuniam credit, ut licet omni conventione cessante, plus tamen sorte recipiat; et utrum eodem reatu criminis involvatur, qui, ut vulgo dicitur, non aliter parabolam iuramenti concedit, donec, quamvis sine exactione, emolumentum aliquod inde percipiat; et an negotiator poena consimili debeat condemnari, qui merces suas longe maiore pretio distrahit, si ad solutionem faciendam prolixioris temporis dilatio prorogetur, quam si ei in continenti pretium persolvatur. Verum quia, quid in his casibus tenendum sit, ex evangelio Lucae manifeste cognoscitur, in quo dicitur: Date mutuum, nihil inde sperantes [cf.Lc6,35]: huiusmodi homines pro intentione lucri, quam habent, cum omnis usura et superabundantia prohibeatur in lege, iudicandi sunt male agere, et ad ea, quae tahter sunt accepta, restituenda in animarum iudicio efficaciter inducendi."]}]}]};
